prompt --application/pages/page_00002
begin
wwv_flow_imp_page.create_page(
 p_id=>2
,p_name=>'Vista Hotel'
,p_alias=>'VISTA-HOTEL'
,p_step_title=>'Vista Hotel'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// ============================================',
unistr('// DANN-ALPES - VERSI\00D3N DEFINITIVA'),
'// ============================================',
'',
'const API = ''https://api-proyecto-3-e75d.onrender.com'';',
'let pagina = 1;',
'let orden = ''fecha'';',
'let totalPaginas = 1;',
'let todas = [];',
'',
'function cargar() {',
'    const contenedor = document.getElementById(''resenas-container'');',
'    if (!contenedor) return;',
'    ',
unistr('    contenedor.innerHTML = ''<div style="text-align:center; padding:50px;">\D83D\DD04 Cargando...</div>'';'),
'    ',
'    fetch(`${API}/hoteles/1/resenas?pagina=1&por_pagina=100`)',
'        .then(r => r.json())',
'        .then(data => {',
'            todas = data.resenas || [];',
'            ',
'            // Ordenar',
'            if (orden === ''fecha'') {',
'                todas.sort((a, b) => new Date(b.fecha_creacion) - new Date(a.fecha_creacion));',
'            } else {',
'                todas.sort((a, b) => (b.votos_utilidad || 0) - (a.votos_utilidad || 0));',
'            }',
'            ',
'            // Paginar',
'            totalPaginas = Math.ceil(todas.length / 5);',
'            const inicio = (pagina - 1) * 5;',
'            const mostrar = todas.slice(inicio, inicio + 5);',
'            ',
'            // Mostrar',
'            let html = `<div style="background:#667eea; color:white; padding:10px; text-align:center; margin-bottom:15px;">',
unistr('                Total: ${todas.length} | Orden: ${orden === ''fecha'' ? ''\D83D\DCC5 Fecha'' : ''\D83D\DC4D Utilidad''} | P\00E1gina ${pagina} de ${totalPaginas}'),
'            </div>`;',
'            ',
'            mostrar.forEach(r => {',
unistr('                const estrellas = ''\2605''.repeat(r.calificacion) + ''\2606''.repeat(5 - r.calificacion);'),
'                let fecha = '''';',
'                try { fecha = new Date(r.fecha_creacion).toLocaleDateString(); } catch(e) {}',
'                ',
'                html += `',
'                    <div style="border:1px solid #ddd; border-radius:10px; padding:15px; margin-bottom:15px; background:white;">',
'                        <div style="display:flex; justify-content:space-between;">',
unistr('                            <strong>\D83D\DC64 Cliente #${r.cliente_id}</strong>'),
'                            <span style="color:#f5b042;">${estrellas}</span>',
'                        </div>',
unistr('                        <div style="color:#888;">\D83D\DCC5 ${fecha}</div>'),
'                        <p>${escapeHtml(r.texto || ''Sin texto'')}</p>',
'                        <button onclick="votar(${r.reserva_id})" style="background:#28a745; color:white; border:none; padding:5px 15px; border-radius:20px;">',
unistr('                            \D83D\DC4D \00DAtil (${r.votos_utilidad || 0})'),
'                        </button>',
unistr('                        ${r.destacada ? ''<span style="background:#ffc107; padding:3px 10px; border-radius:20px; margin-left:10px;">\2B50 Destacada</span>'' : ''''}'),
'                    </div>',
'                `;',
'            });',
'            ',
'            contenedor.innerHTML = html;',
'            ',
'            // Actualizar estado de botones',
'            const btnAnt = document.getElementById(''btn-anterior'');',
'            const btnSig = document.getElementById(''btn-siguiente'');',
'            if (btnAnt) btnAnt.disabled = (pagina <= 1);',
'            if (btnSig) btnSig.disabled = (pagina >= totalPaginas);',
'        })',
'        .catch(e => contenedor.innerHTML = `<div style="color:red;">Error: ${e.message}</div>`);',
'}',
'',
'function votar(id) {',
'    const user = apex.env.APP_USER;',
'    if (!user || user === ''nobody'') {',
unistr('        alert(''Debes iniciar sesi\00F3n para votar'');'),
'        return;',
'    }',
'    ',
'    fetch(`${API}/resenas/${id}/util`, {',
'        method: ''POST'',',
'        headers: { ''Content-Type'': ''application/json'' },',
'        body: JSON.stringify({ usuario_id: user })',
'    })',
'    .then(r => {',
unistr('        if (r.status === 409) alert(''Ya votaste esta rese\00F1a'');'),
'        else if (!r.ok) alert(''Error al votar'');',
'        else {',
unistr('            alert(''\2705 Voto registrado'');'),
'            cargar();',
'        }',
'    })',
'    .catch(e => alert(''Error: '' + e.message));',
'}',
'',
'function escapeHtml(t) {',
'    if (!t) return '''';',
'    const d = document.createElement(''div'');',
'    d.textContent = t;',
'    return d.innerHTML;',
'}',
'',
unistr('// Conectar tus botones (con gui\00F3n, como se ven en la consola)'),
'document.getElementById(''btn-ordenar'').onclick = () => {',
'    orden = orden === ''fecha'' ? ''utilidad'' : ''fecha'';',
'    pagina = 1;',
'    cargar();',
'};',
'document.getElementById(''btn-anterior'').onclick = () => {',
'    if (pagina > 1) {',
'        pagina--;',
'        cargar();',
'    }',
'};',
'document.getElementById(''btn-siguiente'').onclick = () => {',
'    if (pagina < totalPaginas) {',
'        pagina++;',
'        cargar();',
'    }',
'};',
'',
'// Iniciar',
'cargar();'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'17'
,p_last_updated_by=>'CO_B165_SQL_S99_ADMIN'
,p_last_upd_yyyymmddhh24miss=>'20260526203908'
);
