wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(112247371674623357728)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PROXY_API'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_method    VARCHAR2(10)  := apex_application.g_x02;',
'    l_url       VARCHAR2(4000) := apex_application.g_x01;',
'    l_body      CLOB;',
'    l_response  CLOB;',
'    l_status    NUMBER;',
'BEGIN',
unistr('    -- Si hay cuerpo de la petici\00F3n (para POST/PUT)'),
'    IF apex_application.g_x03 IS NOT NULL THEN',
'        l_body := apex_application.g_x03;',
'    END IF;',
'    ',
unistr('    -- Si no se especific\00F3 m\00E9todo, usar GET por defecto'),
'    IF l_method IS NULL THEN',
'        l_method := ''GET'';',
'    END IF;',
'    ',
unistr('    -- Realizar la petici\00F3n a la API'),
'    l_response := apex_web_service.make_rest_request(',
'        p_url         => l_url,',
'        p_http_method => l_method,',
'        p_body        => l_body',
'    );',
'    ',
unistr('    -- Obtener el c\00F3digo de estado HTTP'),
'    l_status := apex_web_service.g_status_code;',
'    ',
'    -- Devolver la respuesta como JSON',
'    apex_json.open_object;',
'    apex_json.write(''status'', l_status);',
'    apex_json.write(''body'', l_response);',
'    apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
);
end;
