,p_chart_id=>wwv_flow_imp.id(112050074086500752318)
,p_seq=>10
,p_name=>'New'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT null AS link,',
'       TO_CHAR(TRUNC(r.fecha_inicio, ''MM''), ''YYYY-MM'') AS label,',
'       COUNT(r.id_reserva) AS value',
'FROM RESERVA r',
'JOIN HABITACION hab ON r.id_habitacion = hab.id_habitacion',
'JOIN HOTEL h ON hab.id_hotel = h.id_hotel',
'WHERE r.fecha_inicio BETWEEN NVL(:P2_FECHA_INICIO, DATE ''2025-01-01'') ',
