 p_id=>wwv_flow_imp.id(112050076010848752338)
,p_plug_name=>'HUESPEDES POR CIUDAD'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_escape_on_http_output=>'Y'
,p_plug_template=>wwv_flow_imp.id(112046493830500454521)
,p_plug_display_sequence=>70
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    NULL AS "LINK",',
'    TO_CHAR(R.fecha_inicio, ''YYYY-MM'') AS "LABEL",',
'    COUNT(R.id_reserva) AS "VALUE"',
'FROM RESERVA R',
'INNER JOIN HABITACION H ON R.id_habitacion = H.id_habitacion',
'INNER JOIN HOTEL HO ON H.id_hotel = HO.id_hotel',
'INNER JOIN CIUDAD C ON HO.id_ciudad = C.id_ciudad',
'WHERE R.fecha_inicio >= TO_DATE(NVL(:P_FECHA_INICIO, ''2025-01-01''), ''YYYY-MM-DD'')',
'AND R.fecha_inicio <= TO_DATE(NVL(:P_FECHA_FIN, ''2025-12-31''), ''YYYY-MM-DD'')',
'AND (HO.id_hotel = :P_ID_HOTEL OR :P_ID_HOTEL IS NULL)',
'AND (C.id_ciudad = :P_ID_CIUDADES OR :P_ID_CIUDADES IS NULL)',
'GROUP BY TO_CHAR(R.fecha_inicio, ''YYYY-MM'')',
'ORDER BY TO_CHAR(R.fecha_inicio, ''YYYY-MM'')'))
,p_plug_source_type=>'NATIVE_JET_CHART'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
);
