,p_plug_name=>'INGRESOS POR HOTEL'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_escape_on_http_output=>'Y'
,p_plug_template=>wwv_flow_imp.id(112046493830500454521)
,p_plug_display_sequence=>80
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    NULL AS link,',
'    h.nombre AS label,',
'    NVL(SUM(r.precio_total), 0) AS value,',
'    c.nombre_ciudad,',
'    COUNT(r.id_reserva) AS total_reservas',
'FROM HOTEL h',
'LEFT JOIN HABITACION hab ON h.id_hotel = hab.id_hotel',
'LEFT JOIN RESERVA r ON hab.id_habitacion = r.id_habitacion',
'                   AND EXTRACT(YEAR FROM r.fecha_inicio) = :P4_ANIO',
'                   AND r.estado IN (''Activa'', ''Completada'')',
'LEFT JOIN CIUDAD c ON h.id_ciudad = c.id_ciudad',
'WHERE (:P4_ID_CIUDAD IS NULL OR h.id_ciudad = :P4_ID_CIUDAD)',
'GROUP BY h.id_hotel, h.nombre, c.nombre_ciudad',
'ORDER BY value DESC'))
,p_plug_source_type=>'NATIVE_JET_CHART'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
);
