 p_id=>wwv_flow_imp.id(112247368941633357701)
,p_plug_name=>unistr('SERVICIO M\00C1S POPULARES')
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_escape_on_http_output=>'Y'
,p_plug_template=>wwv_flow_imp.id(112046493830500454521)
,p_plug_display_sequence=>90
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    NULL AS link,',
'    s.nombre AS label,',
'    COUNT(DISTINCT rs.id_reserva) AS value,',
'    SUM(rs.cantidad) AS total_unidades,',
'    SUM(rs.cantidad * s.precio) AS ingreso_generado',
'FROM SERVICIO s',
'JOIN RESERVA_SERVICIO rs ON s.id_servicio = rs.id_servicio',
'JOIN RESERVA r ON rs.id_reserva = r.id_reserva',
'JOIN HABITACION hab ON r.id_habitacion = hab.id_habitacion',
'JOIN HOTEL h ON hab.id_hotel = h.id_hotel',
'WHERE r.fecha_inicio BETWEEN NVL(:P5_FECHA_INICIO, DATE ''2025-01-01'') ',
'                         AND NVL(:P5_FECHA_FIN, DATE ''2025-12-31'')',
'  AND r.estado IN (''Activa'', ''Completada'')',
'  AND (:P5_ID_HOTEL IS NULL OR h.id_hotel = :P5_ID_HOTEL)',
'GROUP BY s.nombre, s.id_servicio',
'ORDER BY value DESC'))
,p_plug_source_type=>'NATIVE_JET_CHART'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
);
