prompt --application/pages/page_00009
begin
wwv_flow_imp_page.create_page(
 p_id=>9
,p_name=>'Panel Usuario'
,p_alias=>'PANEL-USUARIO'
,p_step_title=>'Panel Usuario'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// ============================================',
unistr('// P\00C1GINA 2 - MI PANEL (CORREGIDO)'),
'// ============================================',
'',
'const API = ''https://api-proyecto-3-e75d.onrender.com'';',
unistr('const usuario = 1001;  // Cambia por un ID v\00E1lido'),
'',
'console.log(''Usuario ID:'', usuario);',
'',
'// ============================================',
'// FUNCIONES GLOBALES',
'// ============================================',
'// ============================================',
'// DECLARAR FUNCIONES GLOBALMENTE',
'// ',
'',
'window.responderResena = responderResena;',
'window.eliminarResenaAdmin = eliminarResenaAdmin;',
'window.destacarResena = destacarResena;',
'window.cargarAdminPanel = cargarAdminPanel;',
'',
'window.eliminarResena = function(reservaId) {',
unistr('    if (!confirm(''\00BFEliminar esta rese\00F1a permanentemente?'')) return;'),
'    ',
'    fetch(`${API}/resenas/${reservaId}/cliente/${usuario}`, {',
'        method: ''DELETE''',
'    })',
'    .then(r => {',
'        if (!r.ok) throw new Error(`HTTP ${r.status}`);',
'        return r.json();',
'    })',
'    .then(() => {',
unistr('        alert(''\2705 Rese\00F1a eliminada'');'),
'        cargarHistorial();',
'    })',
'    .catch(e => alert(''Error: '' + e.message));',
'};',
'',
'window.editarResena = function(reservaId, hotelId, calificacion, texto) {',
'    apex.item(''P2_HOTEL_ID'').setValue(hotelId);',
'    apex.item(''P2_RESERVA_ID'').setValue(reservaId);',
'    apex.item(''P2_CALIFICACION'').setValue(calificacion);',
'    apex.item(''P2_TEXTO'').setValue(texto);',
'    apex.item(''P2_MODO_EDICION'').setValue(1);',
unistr('    apex.item(''P2_RESE\00D1A_EDITAR_ID'').setValue(reservaId);'),
'    ',
'    const btn = document.getElementById(''btn-crear'');',
unistr('    if (btn) btn.innerText = ''Actualizar Rese\00F1a'';'),
'    ',
'    window.scrollTo({ top: 0, behavior: ''smooth'' });',
'};',
'',
'// ============================================',
unistr('// RF1 - CREAR RESE\00D1A'),
'// ============================================',
'function crearResena() {',
'    const hotelId = apex.item(''P2_HOTEL_ID'').getValue() || 1;',
'    const reservaId = apex.item(''P2_RESERVA_ID'').getValue();',
'    const calificacion = apex.item(''P2_CALIFICACION'').getValue();',
'    const texto = apex.item(''P2_TEXTO'').getValue();',
'    ',
'    if (!reservaId || !texto) {',
'        alert(''Completa Reserva ID y Texto'');',
'        return;',
'    }',
'    ',
'    fetch(`${API}/hoteles/${hotelId}/resenas`, {',
'        method: ''POST'',',
'        headers: { ''Content-Type'': ''application/json'' },',
'        body: JSON.stringify({',
'            reserva_id: parseInt(reservaId),',
'            cliente_id: usuario,',
'            calificacion: parseInt(calificacion),',
'            texto: texto',
'        })',
'    })',
'    .then(r => {',
unistr('        if (r.status === 409) throw new Error(''Ya existe una rese\00F1a para esta reserva'');'),
'        if (!r.ok) throw new Error(''Error al crear'');',
'        return r.json();',
'    })',
'    .then(() => {',
unistr('        alert(''\2705 Rese\00F1a creada'');'),
'        limpiarFormulario();',
'        cargarHistorial();',
'    })',
'    .catch(e => alert(''Error: '' + e.message));',
'}',
'',
'function actualizarResena() {',
unistr('    const reservaId = apex.item(''P2_RESE\00D1A_EDITAR_ID'').getValue();'),
'    const calificacion = apex.item(''P2_CALIFICACION'').getValue();',
'    const texto = apex.item(''P2_TEXTO'').getValue();',
'    ',
'    fetch(`${API}/resenas/${reservaId}`, {',
'        method: ''PUT'',',
'        headers: { ''Content-Type'': ''application/json'' },',
'        body: JSON.stringify({',
'            cliente_id: usuario,',
'            calificacion: parseInt(calificacion),',
'            texto: texto',
'        })',
'    })',
'    .then(r => {',
'        if (!r.ok) throw new Error(''Error'');',
'        return r.json();',
'    })',
'    .then(() => {',
unistr('        alert(''\2705 Rese\00F1a actualizada'');'),
'        limpiarFormulario();',
'        cargarHistorial();',
'    })',
'    .catch(e => alert(''Error: '' + e.message));',
'}',
'',
'// ============================================',
'// RF6 - CARGAR HISTORIAL',
'// ============================================',
'function cargarHistorial() {',
'    const container = document.getElementById(''historial-container'');',
'    if (!container) return;',
'    ',
'    container.innerHTML = ''Cargando...'';',
'    ',
'    fetch(`${API}/clientes/${usuario}/resenas`)',
'        .then(r => r.json())',
'        .then(data => {',
'            if (!data || data.length === 0) {',
unistr('                container.innerHTML = ''<p>No has escrito ninguna rese\00F1a.</p>'';'),
'                return;',
'            }',
'            ',
unistr('            let html = ''<h3>Mis Rese\00F1as</h3>'';'),
'            data.forEach(r => {',
'                html += `',
'                    <div style="border:1px solid #ddd; padding:10px; margin:10px 0; border-radius:8px;">',
unistr('                        <strong>Hotel #${r.hotel_id}</strong> - Calificaci\00F3n: ${r.calificacion}/5<br>'),
'                        Reserva #${r.reserva_id}<br>',
'                        Texto: ${r.texto || ''Sin texto''}<br>',
unistr('                        Votos \00FAtiles: ${r.votos_utilidad || 0}<br>'),
unistr('                        Estado: ${r.eliminada ? ''\274C Eliminada'' : ''\2705 Activa''}<br>'),
'                        ${!r.eliminada ? `',
unistr('                            <button onclick="editarResena(''${r.reserva_id}'', ${r.hotel_id}, ${r.calificacion}, \005C`${escapeHtml(r.texto)}\005C`)">\270F\FE0F Editar</button>'),
unistr('                            <button onclick="eliminarResena(${r.reserva_id})">\D83D\DDD1\FE0F Eliminar</button>'),
'                        ` : ''''}',
'                        <hr>',
'                    </div>',
'                `;',
'            });',
'            container.innerHTML = html;',
'        })',
'        .catch(e => container.innerHTML = ''Error: '' + e.message);',
'}',
'',
'function limpiarFormulario() {',
'    apex.item(''P2_HOTEL_ID'').setValue('''');',
'    apex.item(''P2_RESERVA_ID'').setValue('''');',
'    apex.item(''P2_CALIFICACION'').setValue(''5'');',
'    apex.item(''P2_TEXTO'').setValue('''');',
'    apex.item(''P2_MODO_EDICION'').setValue(0);',
unistr('    apex.item(''P2_RESE\00D1A_EDITAR_ID'').setValue('''');'),
'    ',
'    const btn = document.getElementById(''btn-crear'');',
unistr('    if (btn) btn.innerText = ''Crear Rese\00F1a'';'),
'}',
'',
'function escapeHtml(t) {',
'    if (!t) return '''';',
'    const d = document.createElement(''div'');',
'    d.textContent = t;',
'    return d.innerHTML;',
'}',
'',
'// ============================================',
unistr('// CONECTAR BOT\00D3N CREAR'),
'// ============================================',
'const btnCrear = document.getElementById(''btn-crear'');',
'if (btnCrear) {',
'    btnCrear.onclick = () => {',
'        const modo = apex.item(''P2_MODO_EDICION'').getValue();',
'        if (modo == 1) actualizarResena();',
'        else crearResena();',
'    };',
unistr('    console.log(''\2705 Bot\00F3n conectado'');'),
'}',
'// ============================================',
'// PARTE DE ADMINISTRADOR (RF7, RF8, RF9)',
'// ============================================',
'',
'// Verificar si el usuario es administrador',
'const esAdmin = (apex.env.APP_USER === ''ADMIN'');',
unistr('console.log(''\00BFEs administrador?'', esAdmin);'),
'',
'// ============================================',
unistr('// RF7 - RESPONDER RESE\00D1A'),
'// ============================================',
'function responderResena(reservaId, respuesta) {',
'    if (!respuesta || !respuesta.trim()) {',
unistr('        alert(''La respuesta no puede estar vac\00EDa'');'),
'        return;',
'    }',
'    ',
'    fetch(`${API}/resenas/${reservaId}/respuesta`, {',
'        method: ''PUT'',',
'        headers: { ''Content-Type'': ''application/json'' },',
'        body: JSON.stringify({ respuesta: respuesta })',
'    })',
'    .then(r => {',
'        if (!r.ok) throw new Error(''Error al guardar respuesta'');',
'        return r.json();',
'    })',
'    .then(() => {',
unistr('        alert(''\2705 Respuesta guardada'');'),
'        cargarAdminPanel();',
unistr('        cargarHistorial();  // Actualizar tambi\00E9n el historial'),
'    })',
'    .catch(e => alert(''Error: '' + e.message));',
'}',
'',
'// ============================================',
unistr('// RF8 - ELIMINAR RESE\00D1A (ADMIN)'),
'// ============================================',
'function eliminarResenaAdmin(reservaId) {',
unistr('    if (!confirm(''\00BFEliminar esta rese\00F1a como administrador? Esta acci\00F3n no se puede deshacer.'')) return;'),
'    ',
'    fetch(`${API}/resenas/${reservaId}/admin`, {',
'        method: ''DELETE''',
'    })',
'    .then(r => {',
'        if (!r.ok) throw new Error(''Error al eliminar'');',
'        return r.json();',
'    })',
'    .then(() => {',
unistr('        alert(''\2705 Rese\00F1a eliminada por administrador'');'),
'        cargarAdminPanel();',
'        cargarHistorial();',
'    })',
'    .catch(e => alert(''Error: '' + e.message));',
'}',
'',
'// ============================================',
unistr('// RF9 - DESTACAR RESE\00D1A'),
'// ============================================',
'function destacarResena(hotelId, reservaId) {',
unistr('    if (!confirm(''\00BFDestacar esta rese\00F1a? Solo puede haber una destacada por hotel.'')) return;'),
'    ',
'    fetch(`${API}/hoteles/${hotelId}/resenas/${reservaId}/destacar`, {',
'        method: ''PUT''',
'    })',
'    .then(r => {',
'        if (!r.ok) throw new Error(''Error al destacar'');',
'        return r.json();',
'    })',
'    .then(() => {',
unistr('        alert(''\2B50 Rese\00F1a destacada correctamente'');'),
'        cargarAdminPanel();',
'        cargarHistorial();',
'    })',
'    .catch(e => alert(''Error: '' + e.message));',
'}',
'',
'// ============================================',
unistr('// CARGAR PANEL DE ADMINISTRACI\00D3N'),
'// ============================================',
'function cargarAdminPanel() {',
'    const container = document.getElementById(''admin-container'');',
'    if (!container) return;',
'    ',
'    if (!esAdmin) {',
'        container.innerHTML = '''';',
'        return;',
'    }',
'    ',
unistr('    container.innerHTML = ''<h3>\D83D\DCCB Panel de Administraci\00F3n</h3><p>Cargando rese\00F1as...</p>'';'),
'    ',
unistr('    // Obtener rese\00F1as recientes de todos los hoteles'),
unistr('    // Usamos el hotel 1 como ejemplo, idealmente traer\00EDas todas'),
'    fetch(`${API}/hoteles/1/resenas?orden=fecha&pagina=1&por_pagina=20`)',
'        .then(r => r.json())',
'        .then(data => {',
'            if (!data.resenas || data.resenas.length === 0) {',
unistr('                container.innerHTML = ''<h3>\D83D\DCCB Panel de Administraci\00F3n</h3><p>No hay rese\00F1as para moderar.</p>'';'),
'                return;',
'            }',
'            ',
unistr('            let html = ''<h3>\D83D\DCCB Panel de Administraci\00F3n</h3>'';'),
'            html += ''<div style="background:#f0f0f0; padding:10px; margin-bottom:15px;">'';',
unistr('            html += ''<strong>Total de rese\00F1as a moderar:</strong> '' + data.resenas.length;'),
'            html += ''</div>'';',
'            ',
'            data.resenas.forEach(r => {',
'                const fecha = new Date(r.fecha_creacion).toLocaleDateString();',
'                const respuestaActual = r.respuesta_admin?.texto || '''';',
'                ',
'                html += `',
'                    <div style="border:1px solid #ddd; border-radius:8px; padding:15px; margin-bottom:15px; background:white;">',
'                        <div style="display:flex; justify-content:space-between; flex-wrap:wrap;">',
'                            <div>',
'                                <strong>Hotel #${r.cliente_id ? ''?'' : ''1''}</strong> - ',
'                                Reserva #${r.reserva_id}<br>',
'                                <strong>Cliente:</strong> #${r.cliente_id}<br>',
unistr('                                <strong>Calificaci\00F3n:</strong> ${r.calificacion}/5<br>'),
'                                <strong>Fecha:</strong> ${fecha}',
'                            </div>',
unistr('                            ${r.destacada ? ''<span style="background:#ffc107; padding:5px 10px; border-radius:15px;">\2B50 DESTACADA</span>'' : ''''}'),
'                        </div>',
unistr('                        <p style="margin:10px 0;"><strong>Rese\00F1a:</strong> ${escapeHtml(r.texto || ''Sin texto'')}</p>'),
'                        <div style="margin:10px 0;">',
'                            <strong>Respuesta actual:</strong><br>',
'                            <textarea id="respuesta-${r.reserva_id}" rows="2" style="width:100%; padding:8px; margin-top:5px;">${escapeHtml(respuestaActual)}</textarea>',
'                        </div>',
'                        <div style="display:flex; gap:10px; flex-wrap:wrap;">',
'                            <button onclick="responderResena(${r.reserva_id}, document.getElementById(''respuesta-${r.reserva_id}'').value)" ',
'                                    style="background:#28a745; color:white; border:none; padding:8px 15px; border-radius:5px; cursor:pointer;">',
unistr('                                \D83D\DCAC Guardar Respuesta'),
'                            </button>',
'                            <button onclick="eliminarResenaAdmin(${r.reserva_id})" ',
'                                    style="background:#dc3545; color:white; border:none; padding:8px 15px; border-radius:5px; cursor:pointer;">',
unistr('                                \D83D\DDD1\FE0F Eliminar Rese\00F1a'),
'                            </button>',
'                            ${!r.destacada ? `',
'                                <button onclick="destacarResena(1, ${r.reserva_id})" ',
'                                        style="background:#ffc107; color:#333; border:none; padding:8px 15px; border-radius:5px; cursor:pointer;">',
unistr('                                    \2B50 Destacar'),
'                                </button>',
'                            ` : ''''}',
'                        </div>',
'                    </div>',
'                `;',
'            });',
'            ',
'            container.innerHTML = html;',
'        })',
'        .catch(e => {',
'            console.error(''Error:'', e);',
unistr('            container.innerHTML = ''<h3>\D83D\DCCB Panel de Administraci\00F3n</h3><p style="color:red;">Error al cargar rese\00F1as</p>'';'),
'        });',
'}',
'',
'// Si es admin, cargar el panel',
'if (esAdmin) {',
'    cargarAdminPanel();',
'}',
'// ============================================',
'// INICIAR',
'// ============================================',
'cargarHistorial();'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'17'
,p_last_updated_by=>'CO_B165_SQL_S99_ADMIN'
,p_last_upd_yyyymmddhh24miss=>'20260526214106'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(112247371892423357730)
,p_plug_name=>'Panel Container'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(112046493830500454521)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_source=>'<div id="panel-container"></div>'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
,p_attribute_01=>'N'
,p_attribute_02=>'HTML'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(112247372586038357737)
,p_plug_name=>'historial-container'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(112046493830500454521)
,p_plug_display_sequence=>70
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div id="historial-container">',
'    Cargando historial...',
