begin
wwv_flow_imp_page.create_page(
 p_id=>11
,p_name=>unistr('Reservar habitaci\00F3n')
,p_alias=>unistr('RESERVAR-HABITACI\00D3N')
,p_step_title=>unistr('Reservar habitaci\00F3n')
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'23'
,p_last_updated_by=>'CO_B165_SQL_S99_ADMIN'
,p_last_upd_yyyymmddhh24miss=>'20260427024327'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(112050075680756752334)
,p_plug_name=>'New'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(112046434996060454483)
,p_plug_display_sequence=>100
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_column=>1
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT th.id_tipo,',
'       th.nombre_tipo,',
'       th.capacidad,',
'       th.tipo_vista,',
'       th.dimensiones,',
'       CASE ',
'           WHEN :P8_FECHA_INICIO BETWEEN DATE ''2025-06-01'' AND DATE ''2025-07-31''',
'                OR :P8_FECHA_INICIO BETWEEN DATE ''2025-12-01'' AND DATE ''2026-01-31''',
'           THEN th.costo_temporada_alta',
'           ELSE th.costo_temporada_baja',
'       END AS precio_por_noche,',
'       th.num_habitaciones - NVL(reservadas.reservadas, 0) AS disponibles',
'FROM TIPO_HABITACION th',
'LEFT JOIN (',
'    SELECT h.id_tipo, COUNT(r.id_reserva) AS reservadas',
'    FROM HABITACION h',
'    JOIN RESERVA r ON h.id_habitacion = r.id_habitacion',
'    WHERE r.estado = ''Activa''',
'      AND r.fecha_inicio < NVL(:P8_FECHA_FIN, DATE ''9999-12-31'')',
'      AND r.fecha_fin > NVL(:P8_FECHA_INICIO, DATE ''1900-01-01'')',
'    GROUP BY h.id_tipo',
') reservadas ON th.id_tipo = reservadas.id_tipo',
'WHERE (:P8_ID_HOTEL IS NULL OR th.id_hotel = :P8_ID_HOTEL)',
'  AND th.capacidad >= (NVL(:P8_NUM_ADULTOS,1) + NVL(:P8_NUM_MENORES,0))',
'  AND (th.num_habitaciones - NVL(reservadas.reservadas, 0)) > 0',
'ORDER BY th.nombre_tipo'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
,p_show_total_row_count=>false
);
