prompt --application/pages/page_00012
begin
wwv_flow_imp_page.create_page(
 p_id=>12
,p_name=>'Consultas'
,p_alias=>'CONSULTAS'
,p_step_title=>'Consultas'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// ============================================',
'// RFC1 - TOP 10 HOTELES (CON TIMEOUT Y ERRORES)',
'// ============================================',
'',
'console.log(''=== INICIANDO RFC1 ==='');',
'const API = ''https://api-proyecto-3-e75d.onrender.com'';',
'',
'function cargarTopHoteles() {',
'    const container = document.getElementById(''top-hoteles-container'');',
'    if (!container) {',
unistr('        console.error(''\274C Contenedor no encontrado'');'),
'        return;',
'    }',
'    ',
unistr('    console.log(''\2705 Contenedor encontrado'');'),
'    ',
unistr('    container.innerHTML = ''<div style="text-align:center; padding:20px;">\D83D\DD04 Conectando con la API...</div>'';'),
'    ',
'    const url = ''https://api-proyecto-3-e75d.onrender.com/consultas/top-hoteles?fecha_inicio=2024-01-01&fecha_fin=2026-12-31'';',
unistr('    console.log(''\D83D\DCE1 URL:'', url);'),
'    ',
'    // Timeout de 10 segundos',
'    const controller = new AbortController();',
'    const timeoutId = setTimeout(() => controller.abort(), 10000);',
'    ',
'    fetch(url, { signal: controller.signal })',
'        .then(response => {',
'            clearTimeout(timeoutId);',
unistr('            console.log(''\D83D\DCE1 Status:'', response.status);'),
'            if (!response.ok) throw new Error(`HTTP ${response.status}`);',
'            return response.json();',
'        })',
'        .then(data => {',
unistr('            console.log(''\D83D\DCCA Datos recibidos:'', data);'),
'            ',
'            if (!data || data.length === 0) {',
unistr('                container.innerHTML = ''<p>\D83D\DCCA No hay datos en el per\00EDodo seleccionado</p>'';'),
'                return;',
'            }',
'            ',
'            let html = `',
'                <div style="background:linear-gradient(135deg, #667eea, #764ba2); color:white; padding:10px; border-radius:10px; margin-bottom:15px; text-align:center;">',
unistr('                    \D83C\DFC6 TOP 10 HOTELES'),
'                </div>',
'                <table style="width:100%; border-collapse:collapse;">',
'                    <thead><tr style="background:#333; color:white;">',
'                        <th style="padding:10px;">#</th>',
'                        <th style="padding:10px;">Hotel ID</th>',
unistr('                        <th style="padding:10px;">\2B50 Calificaci\00F3n</th>'),
unistr('                        <th style="padding:10px;">\D83D\DCDD Rese\00F1as</th>'),
'                    </tr></thead>',
'                    <tbody>',
'            `;',
'            ',
'            data.slice(0, 10).forEach((hotel, index) => {',
'                const calif = hotel.calificacion_promedio || 0;',
unistr('                const estrellas = ''\2605''.repeat(Math.round(calif)) + ''\2606''.repeat(5 - Math.round(calif));'),
'                ',
'                html += `',
'                    <tr style="border-bottom:1px solid #ddd;">',
'                        <td style="padding:10px; text-align:center;">${index + 1}</td>',
'                        <td style="padding:10px;">Hotel #${hotel.hotel_id}</td>',
'                        <td style="padding:10px;"><span style="color:#f5b042;">${estrellas}</span> ${calif.toFixed(2)}</td>',
'                        <td style="padding:10px; text-align:center;">${hotel.total_resenas}</td>',
'                    </table>',
'                `;',
'            });',
'            ',
'            html += `</tbody>}</div>`;',
'            container.innerHTML = html;',
'        })',
'        .catch(error => {',
'            clearTimeout(timeoutId);',
unistr('            console.error(''\274C Error:'', error);'),
'            ',
'            let mensaje = error.message;',
'            if (error.name === ''AbortError'') {',
unistr('                mensaje = ''La API no respondi\00F3 (timeout). Verifica que el servicio est\00E9 activo.'';'),
'            }',
'            ',
'            container.innerHTML = `',
'                <div style="color:red; padding:20px; text-align:center; border:1px solid red; border-radius:8px;">',
unistr('                    \274C Error: ${mensaje}<br><br>'),
'                    <button onclick="cargarTopHoteles()" style="padding:8px 16px;">Reintentar</button>',
'                </div>',
'            `;',
'        });',
'}',
'',
'',
'// ============================================',
unistr('// RFC2 - EVOLUCI\00D3N DE REPUTACI\00D3N MES A MES'),
'// ============================================',
'',
'console.log(''=== RFC2 - Inicializando ==='');',
'',
'function cargarEvolucion() {',
'    const container = document.getElementById(''evolucion-container'');',
'    if (!container) {',
unistr('        console.error(''\274C No se encuentra evolucion-container'');'),
'        return;',
'    }',
'    ',
'    const hotelId = apex.item(''P3_HOTEL_ID'')?.getValue();',
'    const anio = apex.item(''P3_ANIO'')?.getValue() || 2026;',
'    ',
'    if (!hotelId || hotelId.trim() === '''') {',
unistr('        container.innerHTML = ''<p style="color:orange;">\26A0\FE0F Ingresa un ID de hotel (ej: 1, 2, 3...)</p>'';'),
'        return;',
'    }',
'    ',
unistr('    console.log(`Cargando evoluci\00F3n: Hotel #${hotelId}, A\00F1o ${anio}`);'),
unistr('    container.innerHTML = ''<div style="text-align:center; padding:20px;">\D83D\DD04 Cargando evoluci\00F3n del hotel '' + hotelId + ''...</div>'';'),
'    ',
'    fetch(`${API}/hoteles/${hotelId}/reputacion?anio=${anio}`)',
'        .then(r => {',
'            console.log(`Respuesta HTTP: ${r.status}`);',
'            if (r.status === 404) throw new Error(`Hotel #${hotelId} no encontrado`);',
'            if (!r.ok) throw new Error(`HTTP ${r.status}`);',
'            return r.json();',
'        })',
'        .then(data => {',
'            console.log(''Datos recibidos:'', data);',
'            ',
'            if (!data || data.length === 0) {',
unistr('                container.innerHTML = `<p>\D83D\DCCA No hay rese\00F1as para el Hotel #${hotelId} en ${anio}</p>`;'),
'                return;',
'            }',
'            ',
'            // Crear arrays para los 12 meses',
'            const mesesNombres = [''Enero'', ''Febrero'', ''Marzo'', ''Abril'', ''Mayo'', ''Junio'', ''Julio'', ''Agosto'', ''Septiembre'', ''Octubre'', ''Noviembre'', ''Diciembre''];',
'            const calificaciones = new Array(12).fill(null);',
'            const totalResenas = new Array(12).fill(0);',
'            ',
'            // Llenar datos recibidos',
'            data.forEach(item => {',
'                const mesNumero = parseInt(item.mes.split(''-'')[1]);',
'                calificaciones[mesNumero - 1] = item.calificacion_promedio;',
'                totalResenas[mesNumero - 1] = item.total_resenas;',
'            });',
'            ',
'            // Calcular promedio anual (solo meses con datos)',
'            const mesesConDatos = calificaciones.filter(v => v !== null && !isNaN(v));',
'            let promedioAnual = 0;',
'            if (mesesConDatos.length > 0) {',
'                promedioAnual = mesesConDatos.reduce((sum, v) => sum + v, 0) / mesesConDatos.length;',
'            }',
'            ',
unistr('            const tendencia = promedioAnual >= 4 ? ''\D83D\DC4D Excelente'' : (promedioAnual >= 3 ? ''\D83D\DCCA Regular'' : ''\26A0\FE0F Necesita mejorar'');'),
'            const maxCalificacion = 5;',
'            ',
unistr('            // Generar gr\00E1fico de barras'),
'            let barrasHtml = ''<div style="display:flex; align-items:flex-end; gap:8px; height:250px; margin-top:20px;">'';',
'            ',
'            for (let i = 0; i < 12; i++) {',
'                const valor = calificaciones[i];',
'                const altura = valor ? (valor / maxCalificacion) * 200 : 0;',
'                let color = ''#e9ecef'';',
'                if (valor) {',
'                    if (valor >= 4) color = ''#28a745'';',
'                    else if (valor >= 3) color = ''#ffc107'';',
'                    else color = ''#dc3545'';',
'                }',
'                ',
'                barrasHtml += `',
'                    <div style="flex:1; text-align:center;">',
'                        <div style="background:${color}; height:${altura}px; border-radius:5px 5px 0 0; transition:height 0.3s; min-height:5px;"></div>',
'                        <div style="margin-top:8px; font-size:11px; font-weight:bold;">${mesesNombres[i].substring(0,3)}</div>',
'                        <div style="font-size:12px; font-weight:bold; color:#333;">${valor !== null ? valor.toFixed(1) : ''-''}</div>',
'                    </div>',
'                `;',
'            }',
'            ',
'            barrasHtml += ''</div>'';',
'            ',
'            // Generar tabla de datos',
'            let tablaHtml = `',
unistr('                <h4 style="margin-top:25px;">\D83D\DCCA Datos mensuales</h4>'),
'                <table style="width:100%; border-collapse:collapse;">',
'                    <thead>',
'                        <tr style="background:#333; color:white;">',
'                            <th style="padding:10px;">Mes</th>',
unistr('                            <th style="padding:10px;">\2B50 Calificaci\00F3n Promedio</th>'),
unistr('                            <th style="padding:10px;">\D83D\DCDD Total Rese\00F1as</th>'),
'                        </tr>',
'                    </thead>',
'                    <tbody>',
'            `;',
'            ',
'            for (let i = 0; i < 12; i++) {',
'                const valor = calificaciones[i];',
'                const total = totalResenas[i];',
unistr('                let estrellas = ''\2606\2606\2606\2606\2606'';'),
'                let valorTexto = ''-'';',
'                let colorTexto = ''#888'';',
'                ',
'                if (valor !== null && !isNaN(valor)) {',
'                    valorTexto = valor.toFixed(2);',
unistr('                    estrellas = ''\2605''.repeat(Math.round(valor)) + ''\2606''.repeat(5 - Math.round(valor));'),
'                    colorTexto = ''#333'';',
'                }',
'                ',
'                tablaHtml += `',
'                    <tr style="border-bottom:1px solid #ddd;">',
'                        <td style="padding:8px;"><strong>${mesesNombres[i]}</strong></td>',
'                        <td style="padding:8px;">',
'                            <span style="color:#f5b042;">${estrellas}</span> ',
'                            <span style="color:${colorTexto};">${valorTexto}</span>',
'                        </td>',
'                        <td style="padding:8px; text-align:center;">${total}</td>',
'                    </tr>',
'                `;',
'            }',
'            ',
'            tablaHtml += `</tbody>}\x7d</div>`;',
'            ',
'            // HTML completo',
'            const html = `',
'                <div style="background:linear-gradient(135deg, #667eea, #764ba2); color:white; padding:12px; border-radius:10px; margin-bottom:15px; text-align:center;">',
unistr('                    \D83D\DCC8 Evoluci\00F3n Hotel #${hotelId} - A\00F1o ${anio}'),
'                </div>',
'                <div style="background:#f0f2f5; padding:12px; border-radius:8px; margin-bottom:20px; text-align:center;">',
unistr('                    <strong>\2B50 Promedio anual: ${promedioAnual.toFixed(2)} \2605</strong> - ${tendencia}'),
unistr('                    <span style="margin-left:15px;">\D83D\DCCA Basado en ${mesesConDatos.length} meses con datos</span>'),
'                </div>',
'                ${barrasHtml}',
'                ${tablaHtml}',
'            `;',
'            ',
'            container.innerHTML = html;',
'        })',
'        .catch(e => {',
'            console.error(''Error:'', e);',
unistr('            container.innerHTML = `<p style="color:red;">\274C ${e.message}</p>`;'),
'        });',
'}',
'',
'',
'// ============================================',
'// RFC3 - PERFIL COMPARATIVO (SIN AJAX)',
'// ============================================',
'',
'// MAPEO MANUAL DE HOTELES POR CIUDAD',
unistr('// Necesitas mantener esto actualizado seg\00FAn tu tabla HOTELES_CIUDAD'),
'const hotelesPorCiudad = {',
unistr('    ''Bogot\00E1'': [1, 2, 3],'),
unistr('    ''Medell\00EDn'': [4],'),
'    ''Cali'': [6],',
'    ''Cartagena'': [5],',
'    ''Barranquilla'': [7]',
'};',
'',
'function cargarComparativo() {',
'    const container = document.getElementById(''comparativo-container'');',
'    if (!container) {',
'        console.error(''No se encuentra comparativo-container'');',
'        return;',
'    }',
'    ',
'    const ciudad = apex.item(''P3_CIUDAD'')?.getValue();',
'    ',
'    if (!ciudad || ciudad.trim() === '''') {',
unistr('        container.innerHTML = ''<p style="color:orange;">\26A0\FE0F Selecciona una ciudad</p>'';'),
'        return;',
'    }',
'    ',
unistr('    container.innerHTML = ''<div style="text-align:center; padding:20px;">\D83D\DD04 Cargando comparativo...</div>'';'),
'    ',
'    // Obtener IDs de hoteles de la ciudad seleccionada',
'    const hotelesIds = hotelesPorCiudad[ciudad] || [];',
'    ',
'    if (hotelesIds.length === 0) {',
unistr('        container.innerHTML = `<p>\26A0\FE0F No hay hoteles registrados para ${ciudad}</p>`;'),
'        return;',
'    }',
'    ',
'    const url = `${API}/consultas/comparativo-ciudad?ciudad=${ciudad}&hotel_ids=${hotelesIds.join('','')}`;',
'    console.log(''URL:'', url);',
'    ',
'    fetch(url)',
'        .then(r => {',
'            if (!r.ok) throw new Error(`HTTP ${r.status}`);',
'            return r.json();',
'        })',
'        .then(data => {',
'            if (!data || data.length === 0) {',
unistr('                container.innerHTML = `<p>\D83D\DCCA No hay datos para los hoteles de ${ciudad}</p>`;'),
'                return;',
'            }',
'            ',
'            // Calcular promedio',
'            const suma = data.reduce((sum, h) => sum + h.calificacion_promedio, 0);',
'            const promedioCiudad = (suma / data.length).toFixed(2);',
'            ',
'            let html = `',
'                <div style="background:linear-gradient(135deg, #667eea, #764ba2); color:white; padding:12px; border-radius:10px; text-align:center;">',
unistr('                    \D83C\DFD9\FE0F COMPARATIVO - ${ciudad}'),
'                </div>',
'                <div style="background:#f0f2f5; padding:10px; border-radius:8px; margin:15px 0; text-align:center;">',
unistr('                    \D83D\DCCA Promedio ciudad: ${promedioCiudad} \2605'),
'                </div>',
'                <table style="width:100%; border-collapse:collapse;">',
'                    <thead>',
'                        <tr style="background:#333; color:white;">',
'                            <th style="padding:10px;">Hotel</th>',
unistr('                            <th style="padding:10px;">\2B50 Calificaci\00F3n</th>'),
unistr('                            <th style="padding:10px;">\D83D\DCDD Rese\00F1as</th>'),
unistr('                            <th style="padding:10px;">\D83D\DCAC % Respuesta</th>'),
unistr('                            <th style="padding:10px;">\2B50 % Destacadas</th>'),
'                            <th style="padding:10px;">Vs Ciudad</th>',
'                        </td>',
'                    </thead>',
'                    <tbody>',
'            `;',
'            ',
'            data.forEach(hotel => {',
'                const vs = (hotel.calificacion_promedio - promedioCiudad).toFixed(2);',
'                const vsColor = vs >= 0 ? ''green'' : ''red'';',
unistr('                const vsSigno = vs >= 0 ? ''\25B2'' : ''\25BC'';'),
'                ',
'                html += `',
'                    <tr style="border-bottom:1px solid #ddd;">',
'                        <td style="padding:8px;"><strong>Hotel #${hotel.hotel_id}</strong></td>',
unistr('                        <td style="padding:8px; text-align:center;">${hotel.calificacion_promedio} \2605</td>'),
'                        <td style="padding:8px; text-align:center;">${hotel.total_resenas}</td>',
'                        <td style="padding:8px; text-align:center;">${hotel.porcentaje_con_respuesta}%</td>',
'                        <td style="padding:8px; text-align:center;">${hotel.porcentaje_destacadas}%</td>',
'                        <td style="padding:8px; text-align:center; color:${vsColor};">${vsSigno} ${Math.abs(vs)}</td>',
'                    </tr>',
'                `;',
'            });',
'            ',
'            html += `</tbody></div>`;',
'            container.innerHTML = html;',
'        })',
'        .catch(e => {',
'            console.error(''Error:'', e);',
unistr('            container.innerHTML = `<p style="color:red;">\274C Error: ${e.message}</p>`;'),
'        });',
'}',
'',
unistr('// Conectar bot\00F3n'),
'const btnComp = document.getElementById(''btn-comparativo'');',
'if (btnComp) {',
'    btnComp.onclick = cargarComparativo;',
'}',
unistr('// Cargar evoluci\00F3n al iniciar (si existe el contenedor)'),
'setTimeout(function() {',
'    if (document.getElementById(''evolucion-container'')) {',
'        cargarEvolucion();',
'    }',
'}, 200);',
unistr('// Conectar bot\00F3n'),
'const btnTop = document.getElementById(''btn-top-hoteles'');',
'if (btnTop) {',
'    btnTop.onclick = cargarTopHoteles;',
unistr('    console.log(''\2705 Bot\00F3n conectado'');'),
'} else {',
unistr('    console.error(''\274C Bot\00F3n no encontrado'');'),
'}',
'',
'// Ejecutar',
'cargarTopHoteles();'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'17'
,p_last_updated_by=>'CO_B165_SQL_S99_ADMIN'
,p_last_upd_yyyymmddhh24miss=>'20260527013512'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(112247373075841357742)
,p_plug_name=>'Top Hoteles'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(112046493830500454521)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div id="top-hoteles-container">',
